-- D-30 Chemical Control Program: FSQM-032 + FRM-402 Chemical Register, both DRAFT.
--
-- SQF 11.2.5.2, 11.2.5.3 and 11.6.4.1-.7 are Non-Compliant. Numbers from the remediation workbook:
-- FSQM-032 reserved; "FRM-4xx register" -> FRM-402 (FRM-401 taken).
--
-- Owner's answers, 2026-09-21: chemicals kept separately but not locked (a locker is planned);
-- Production staff handle them; no PPE, eyewash or spill kit yet (to be bought); empty containers
-- rinsed and put in the trash or recycling.
--
-- FRM-402's fixed, deletable rows ARE the register (the FRM-705 / FRM-508 shape), pre-filled with the
-- five chemicals in the Chemical Safety Data Sheets document and the two food-grade lubricants the SOPs
-- use. Section 3 asks Yes / Not yet for the locker, PPE, eyewash, spill kit and SDS binder, so the gap is
-- on the record. The monthly store check is FRM-913's existing 11.6.4 row, not a new form.

begin;

do $guard$
begin
  if exists (select 1 from public.sop_documents where sop_number in ('FSQM-032', 'FRM-402')) then
    raise exception 'FSQM-032 or FRM-402 already exists.';
  end if;
  if (select count(*) from public.sop_documents
       where sop_number in ('FRM-903', 'FRM-952', 'FRM-913', 'FSQM-018', 'FSQM-029', 'SOP-502', 'SOP-503', 'SOP-905')) <> 8 then
    raise exception 'a document D-30 names does not exist.';
  end if;
  if not exists (select 1 from public.sop_documents where title = 'Chemical Safety Data Sheets (SDS)' and status = 'active') then
    raise exception 'Chemical Safety Data Sheets document not active.';
  end if;
end $guard$;

insert into public.sop_documents
  (sop_number, title, type, category, status, revision, sqf_reference, sqf_required, content)
values
  ('FSQM-032', 'Chemical Control Program', 'fsqm', 'Food Safety Quality Manual', 'draft', 'New',
   '11.2.5.2, 11.2.5.3, 11.6.4.1, 11.6.4.2, 11.6.4.3, 11.6.4.4, 11.6.4.5, 11.6.4.6, 11.6.4.7', true, $q${"purpose": "This program states how Adventure Bakery controls the chemicals it uses, so that they cannot contaminate product, packaging or product-contact surfaces and the people who handle them are protected: which chemicals are approved, how they are labelled, stored, mixed and used, and what happens with spills and disposal.", "scope": "Every detergent, sanitizer, cleaner and rinse additive on site, and the food-grade lubricants. No pesticides are kept on site; the pest control contractor brings and removes them.", "definitions": "Chemical register: the rows of the latest submitted FRM-402 entry.\nConcentrate: a chemical as supplied, before dilution.\nWorking container: a spray bottle or bucket holding a chemical diluted for use.", "responsibility": "SQF Practitioner - owns this program, approves every chemical before it is bought, and signs the register.\nManagement team - buys chemicals only from the register, and provides the locker, PPE, eyewash and spill kit.\nProduction staff - handle chemicals only after training under Part 7, mix and use them as their label and SSOP say, and return them to the locker.", "procedure": ["Approved chemicals", "• Only chemicals on the FRM-402 register are brought on site or used (SQF 11.2.5.2, 11.6.4.1).", "• A new chemical is approved by the SQF Practitioner before it is bought: its SDS is filed in the Chemical Safety Data Sheets document, its label is read for use and dilution, and a new FRM-402 entry adds it.", "• The register is re-issued at least once a year, and whenever a chemical is added, changed or removed.", "• No pesticides, rodenticides or insecticides are kept on site. If that changes, they are kept in their own locked space, apart from sanitizers and detergents (SQF 11.6.4.2).", "SDS and labels", "• Every SDS is in the Chemical Safety Data Sheets document in the Team Portal, which all staff can open, and a printed copy is kept in a binder beside the chemical store.", "• Chemicals stay in their original, labelled containers. A working container is labelled with the product name and dilution when it is filled, and is used only for that product (SQF 11.6.4.1, 11.2.5.3).", "• A container with a missing or unreadable label is not used; its contents are disposed of under Part 8.", "The chemical store", "• Chemicals are kept in the chemical locker: lockable, signed Chemical Storage - Authorised Staff Only, ventilated, and away from ingredients, packaging, utensils and product-contact surfaces - never above them (SQF 11.6.4.2).", "• The locker is kept locked when nobody is taking chemicals from it. Only trained Production staff and the Management team open it.", "• Nothing else is kept in it: no utensils, packaging, food or clothing. Food-grade lubricants are kept on their own shelf.", "• During production, the day's working solutions of sanitizer and detergent may be kept at the sink and the washer, labelled; the washer's rinse additive stays connected. Concentrate goes back to the locker after each use, and working solutions are emptied at the end of the day (SQF 11.6.4.4).", "> THE LOCKER IS NOT YET INSTALLED. Chemicals are kept on their own shelf, away from food, but it does not lock. Until the locker is in place, 11.6.4.2 is not met, and FRM-402 records it as Not yet.", "Mixing and use", "• Every chemical is used only as its label says, at the dilution on the register (SQF 11.6.4.3). For Sani-512, an EPA-registered sanitizer, the label is the law.", "• Sani-512 is mixed at 1:512 and checked with a test strip at about 200 ppm; Dawn Professional is measured at 1-2 oz per 10 gallons. Both are recorded on FRM-903, and each machine's SSOP gives the steps (SQF 11.2.5.3).", "• Chemicals are never mixed with each other, and are never mixed or used over open product, ingredients or packaging.", "• A product-contact surface is touched only by the sanitizer at its label dilution, or by detergent that is rinsed off.", "PPE and first aid", "• Anyone mixing concentrate wears chemical-resistant gloves and safety glasses or goggles. The Sani-512 SDS says it causes severe skin burns and eye damage.", "• An eyewash station or eyewash bottles are kept within reach of the locker and the mixing point, and a first aid kit is kept on site (SQF 11.6.4.5).", "> GLOVES, EYE PROTECTION, EYEWASH AND A SPILL KIT ARE STILL TO BE BOUGHT. Until they are on site, 11.6.4.5 and 11.6.4.7 are not met, and FRM-402 records them as Not yet.", "Spills", "• Put on gloves and eye protection, and keep other people away.", "• Contain the spill with absorbent from the spill kit, scoop it into a bag, seal and label it, then wash the area with water.", "• Chemical on skin or in the eyes: rinse with water for at least 15 minutes, using the eyewash for eyes, and follow the SDS first aid section. Sani-512 in the eyes needs medical help.", "• If a spill reaches ingredients, packaging, product or a product-contact surface, they are held under FSQM-018, and the surface is cleaned and sanitized before use.", "• These instructions are posted beside the chemical locker, with the spill kit: absorbent, bags, a scoop, gloves and goggles (SQF 11.6.4.7).", "Training", "• Production staff who clean are the chemical handlers. Before handling chemicals, each is trained in what each chemical is for, its hazards, mixing and checking it, PPE, storage, spills and disposal (SQF 11.6.4.5).", "• The training is recorded on FRM-952.", "Disposal", "• Primary containers are never reused for anything (SQF 11.6.4.6).", "• Empty containers are rinsed as their label says - Sani-512 is triple-rinsed - bagged, and kept in the locker until the site's waste collection day. They then go out with the trash or recycling, collected by the site's waste collection service.", "• Unused, expired or unlabelled chemical is never poured into a drain unless its label allows it. It is disposed of as its SDS section 13 says, through a hazardous waste drop-off or back to the supplier."], "form_references": "FRM-402 - Chemical Register\nFRM-903 - Daily Sanitation, Pre-Operation & Release Record (mixing checks)\nFRM-952 - Training Competency Verification Record\nFRM-913 - GMP / Food Safety Inspection Record (monthly check of the store, row 11.6.4)", "records": "• FRM-402 entries - the latest submitted entry is the register in force\n• The Chemical Safety Data Sheets document and the printed binder\n• FRM-903 daily mixing checks\n• FRM-952 training records for chemical handlers", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 11.2.5.2, 11.2.5.3 (detergents and sanitizers) and 11.6.4.1 to 11.6.4.7 (hazardous chemicals and toxic substances).\n29 CFR 1910.1200 - OSHA Hazard Communication Standard.\nFIFRA - Sani-512 is an EPA-registered product; its label is the legal instruction for use and disposal.\n\nChemical Safety Data Sheets (reference document) - every SDS.\nThe machine SSOPs (SOP-901 to SOP-906) - mixing steps.\nFSQM-029 Preventive Maintenance Program - lubricants.\nFSQM-018 Non-Conforming Product and Equipment - product a spill may have affected.", "revision_history": "New - 2026-09-21 - DRAFT under D-30, for the nine Non-Compliant findings against 11.2.5.2, 11.2.5.3 and 11.6.4.\n\nWHAT THE SITE DOES NOW (owner, 2026-09-21): chemicals are kept separately but not locked, and a locker is planned; Production staff mix and handle them; there are no gloves, eye protection, eyewash or spill kit yet, and they are to be bought; empty containers are rinsed and put in the trash or recycling.\n\nThe program writes the locker, the PPE, the eyewash and the spill kit in as requirements and says plainly that they are not yet in place, so that the record shows the gap rather than hiding it.\n\nNO PESTICIDES ON SITE is stated on the understanding that the pest control contractor brings and removes them. Confirm before issue."}$q$::jsonb),
  ('FRM-402', 'Chemical Register', 'form', 'Module 11', 'draft', 'New',
   '11.2.5.2, 11.6.4.1', true, jsonb_build_object('form_schema', $f${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": false, "requireVerification": true, "instanceTitleTemplate": "Chemical register - {review_date}"}, "sections": [{"id": "about", "title": "1. How this record works", "fields": [{"id": "how_this_works", "type": "info", "label": "The approved chemical register", "text": "THE ROWS BELOW ARE THE APPROVED CHEMICAL REGISTER (SQF 11.2.5.2, 11.6.4.1). Only chemicals on it are brought on site or used.\n\nA NEW ENTRY is made when a chemical is added, changed or removed, and at least once a year. The latest submitted entry is the register in force.\n\nBEFORE A CHEMICAL IS ADDED, its SDS is filed in the Chemical Safety Data Sheets document and its label is read for use and dilution. Delete a row only when the chemical has left the site."}]}, {"id": "register", "title": "2. Register", "fields": [{"id": "review_date", "type": "date", "label": "Date", "width": "third", "required": true, "defaultToday": true, "showInList": true}, {"id": "reason", "type": "select", "label": "Reason for this entry", "width": "third", "required": true, "showInList": true, "options": ["First issue", "Annual review", "Chemical added", "Chemical changed or removed"]}, {"id": "chemicals", "type": "grid", "label": "Approved chemicals", "rowDialog": true, "rows": {"mode": "fixed", "deletable": true, "labelHeader": "Chemical", "addLabel": "Add chemical", "labels": ["Noble Sani-512 sanitizer", "Dawn Professional Dish Detergent", "Keystone liquid rinse additive", "Green dishwashing liquid", "Mr. Clean Professional Degreaser Floor Cleaner", "NSF H1 food-grade oil", "Beldos food-approved grease"], "defaultValues": [{"type": "Sanitizer", "supplier": "Noble Chemical", "used_for": "Sanitizing food-contact surfaces, no rinse; foot bath", "dilution": "1:512 (1 fl oz per 4 gal, about 200 ppm) for food contact; 1:160 for the foot bath", "hazard": "DANGER - corrosive, causes eye damage; store locked up", "kept_in": "Chemical locker", "sds": "Yes"}, {"type": "Detergent", "supplier": "Procter & Gamble Professional", "used_for": "Manual washing of ware and equipment parts", "dilution": "1-2 oz per 10 gal", "hazard": "WARNING - eye irritant", "kept_in": "Chemical locker", "sds": "Yes"}, {"type": "Rinse additive", "supplier": "Keystone", "used_for": "Pot and pan washer final rinse", "dilution": "Dosed by the washer", "hazard": "See SDS", "kept_in": "At the pot and pan washer (daily-use supply)", "sds": "Yes"}, {"type": "Detergent", "supplier": "", "used_for": "Hand dishwashing - confirm it is still in use", "dilution": "As the label says", "hazard": "See SDS", "kept_in": "Chemical locker", "sds": "Yes"}, {"type": "Cleaner", "supplier": "Procter & Gamble Professional", "used_for": "Floors", "dilution": "As the label says", "hazard": "See SDS", "kept_in": "Chemical locker", "sds": "Yes"}, {"type": "Food-grade lubricant", "supplier": "", "used_for": "Kook-E-King feed-roller bushings (SOP-502)", "dilution": "Neat, a few drops", "hazard": "Food-grade (H1)", "kept_in": "Kept apart from the cleaning chemicals", "sds": "No - obtain"}, {"type": "Food-grade lubricant", "supplier": "Beldos", "used_for": "Beldos 275 seals and O-rings (SOP-503)", "dilution": "Neat, thin film", "hazard": "Food-grade", "kept_in": "Kept apart from the cleaning chemicals", "sds": "No - obtain"}], "guidance": ["• EPA reg. 6836-266-65239. The label is the legal instruction for use (FIFRA).\n• Concentrate: gloves and eye protection when mixing. Checked with a test strip at about 200 ppm and recorded on FRM-903.", "• Measured dose, recorded on FRM-903.", "• Connected to the washer (SOP-905). A spare container is kept in the chemical locker, not beside the washer.", "• If it is no longer used, delete this row and dispose of any stock (FSQM-032 Part 8).", "• Floors only - never on product-contact surfaces.", "• Record the product name and supplier, and file its SDS.\n• Lubricants are covered by FSQM-029 Part 7.", "• File its SDS.\n• Lubricants are covered by FSQM-029 Part 7."]}, "columns": [{"id": "type", "type": "select", "label": "Type", "options": ["Sanitizer", "Detergent", "Rinse additive", "Cleaner", "Food-grade lubricant", "Other"]}, {"id": "supplier", "type": "text", "label": "Supplier"}, {"id": "used_for", "type": "text", "label": "Used for", "width": 2}, {"id": "dilution", "type": "text", "label": "Dilution", "width": 2}, {"id": "hazard", "type": "text", "label": "Main hazard (SDS)", "width": 2}, {"id": "kept_in", "type": "text", "label": "Kept in"}, {"id": "sds", "type": "select", "label": "SDS on file", "options": ["Yes", "No - obtain"], "required": true}]}]}, {"id": "store", "title": "3. Store and safety equipment", "fields": [{"id": "store_info", "type": "info", "label": "Answer as things are today", "text": "\"Not yet\" is an honest answer and is expected until the purchases in FSQM-032 are made."}, {"id": "locker", "type": "select", "label": "Chemical locker installed, signed and locked", "width": "half", "required": true, "options": ["Yes", "Not yet"]}, {"id": "ppe", "type": "select", "label": "Chemical gloves and eye protection available", "width": "half", "required": true, "options": ["Yes", "Not yet"]}, {"id": "eyewash", "type": "select", "label": "Eyewash within reach of the locker and mixing point", "width": "half", "required": true, "options": ["Yes", "Not yet"]}, {"id": "spill_kit", "type": "select", "label": "Spill kit and posted spill instructions", "width": "half", "required": true, "options": ["Yes", "Not yet"]}, {"id": "sds_binder", "type": "select", "label": "Printed SDS binder beside the store", "width": "half", "required": true, "options": ["Yes", "Not yet"]}, {"id": "store_notes", "type": "textarea", "label": "Notes"}, {"id": "prepared_by", "type": "signature", "label": "Prepared by", "role": "filler", "required": true, "statement": "This register lists every chemical on site, as checked on the date shown."}, {"id": "approved_by", "type": "signature", "label": "Approved by the SQF Practitioner", "role": "verifier", "required": true, "statement": "I approve the chemicals on this register for use on site."}]}]}$f$::jsonb));

do $verify$
declare fs jsonb; g jsonb; p jsonb;
begin
  select content->'procedure' into p from public.sop_documents where sop_number = 'FSQM-032';
  if jsonb_array_length(p) <> 37 then raise exception 'FSQM-032 procedure is % lines, expected 37.', jsonb_array_length(p); end if;
  select content->'form_schema' into fs from public.sop_documents where sop_number = 'FRM-402';
  select f into g from jsonb_array_elements(fs->'sections') s, jsonb_array_elements(s->'fields') f where f->>'id' = 'chemicals';
  if jsonb_array_length(g->'rows'->'labels') <> 7 or jsonb_array_length(g->'rows'->'defaultValues') <> 7
     or jsonb_array_length(g->'rows'->'guidance') <> 7 or not (g->'rows'->>'deletable')::boolean then
    raise exception 'FRM-402 register rows mis-built.';
  end if;
  if (select count(*) from jsonb_array_elements(fs->'sections') s, jsonb_array_elements(s->'fields') f
       where f->>'type' = 'signature' and f->>'role' = 'verifier') <> 1 then
    raise exception 'FRM-402 needs one verifier signature.';
  end if;
end $verify$;

commit;
